/* Store-local civil dates. Holiday display is separate from closing rules. */
import {REGION_DATA} from './us-regions.mjs';
export {REGION_DATA};
const dateOf=s=>new Date(s+'T12:00:00Z');
const iso=d=>d.toISOString().slice(0,10);
const shift=(day,n)=>{const d=dateOf(day);d.setUTCDate(d.getUTCDate()+n);return iso(d);};
export const validCalendarDate=s=>typeof s==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(s)&&!Number.isNaN(dateOf(s).getTime())&&iso(dateOf(s))===s;
export function validateCalendar(payload,current={}){
 const reject=()=>{throw new Error('定休日・特別営業日・祝日の設定を確認してください。');};
 const numbers=(v,allowed)=>{if(!Array.isArray(v)||!v.length||v.length>allowed.length||v.some(n=>!Number.isInteger(n)||!allowed.includes(n))||new Set(v).size!==v.length)reject();return [...v];};
 const range=(start,end)=>Array.from({length:end-start+1},(_,i)=>i+start),result={};
 const dates=payload.openDates===undefined?(current.openDates||[]):payload.openDates;if(!Array.isArray(dates)||dates.length>366||dates.some(v=>!validCalendarDate(v)))reject();result.openDates=[...new Set(dates)].sort();
 const note=payload.closureNote===undefined?(current.closureNote||''):payload.closureNote;if(typeof note!=='string'||[...note].length>200||note.includes('\0'))reject();result.closureNote=note.trim();
 const rules=payload.closureRules===undefined?(current.closureRules||[]):payload.closureRules;if(!Array.isArray(rules)||rules.length>24)reject();
 result.closureRules=rules.map(rule=>{if(!rule||typeof rule!=='object'||Array.isArray(rule))reject();const r={type:rule.type};
  if(r.type==='weekly'){r.interval=rule.interval===undefined?1:rule.interval;if(![1,2].includes(r.interval))reject();r.weekdays=numbers(rule.weekdays,range(0,6));if(r.interval===2){if(!validCalendarDate(rule.anchor))reject();r.anchor=rule.anchor;}}
  else if(r.type==='monthlyDates')r.days=numbers(rule.days,range(1,31));
  else if(r.type==='monthlyWeekdays'){r.weekdays=numbers(rule.weekdays,range(0,6));r.weeks=numbers(rule.weeks,[-1,...range(1,5)]);}
  else if(r.type==='monthlyLastDay'){}
  else if(r.type==='unscheduled'){if(!['monthly','irregular'].includes(rule.cadence))reject();r.cadence=rule.cadence;}
  else reject();return r;});
 const region=payload.holidayRegion===undefined?(current.holidayRegion||'US'):payload.holidayRegion;if(!['US','none'].includes(region))reject();result.holidayRegion=region;
 const holidays=payload.regionalHolidays===undefined?(current.regionalHolidays||[]):payload.regionalHolidays;if(!Array.isArray(holidays)||holidays.length>366)reject();
 result.regionalHolidays=holidays.map(h=>{if(!h||!validCalendarDate(h.date)||typeof h.name!=='string'||![...h.name.trim()].length||[...h.name.trim()].length>80||/[\x00-\x1f]/.test(h.name))reject();return {date:h.date,name:h.name.trim()};});
 result.storeState=payload.storeState===undefined?(current.storeState||''):payload.storeState;result.storeRegion=payload.storeRegion===undefined?(current.storeRegion||''):payload.storeRegion;
 if(typeof result.storeState!=='string'||typeof result.storeRegion!=='string')reject();
 if(result.storeState){const selected=REGION_DATA.states[result.storeState]?.regions.find(r=>r.id===result.storeRegion);if(!selected||selected.zone!==(payload.timezone||current.timezone))reject();}else if(result.storeRegion)reject();return result;
}
export function isStoreClosed(settings,day){
 if((settings.openDates||[]).includes(day))return false;if((settings.closedDates||[]).includes(day))return true;
 const d=dateOf(day),weekday=d.getUTCDay(),number=d.getUTCDate();
 return (settings.closureRules||[]).some(r=>{
  if(r.type==='weekly'&&r.weekdays.includes(weekday)){if(r.interval===1)return true;const start=dateOf(r.anchor);start.setUTCDate(start.getUTCDate()-start.getUTCDay());const current=dateOf(day);current.setUTCDate(current.getUTCDate()-weekday);const weeks=Math.round((current-start)/604800000);return weeks>=0&&weeks%2===0;}
  if(r.type==='monthlyDates')return r.days.includes(number);
  if(r.type==='monthlyLastDay')return dateOf(shift(day,1)).getUTCMonth()!==d.getUTCMonth();
  if(r.type==='monthlyWeekdays'&&r.weekdays.includes(weekday))return r.weeks.includes(Math.floor((number-1)/7)+1)||(r.weeks.includes(-1)&&dateOf(shift(day,7)).getUTCMonth()!==d.getUTCMonth());return false;
 });
}
const holidaySpecs=[
 ['newYear',1,1,"New Year’s Day",'元日'],['mlk',1,0,'Birthday of Martin Luther King, Jr.','キング牧師誕生日',3,1],['washington',2,0,"Washington’s Birthday",'ワシントン誕生日',3,1],['memorial',5,0,'Memorial Day','戦没者追悼記念日',-1,1],['juneteenth',6,19,'Juneteenth National Independence Day','ジューンティーンス'],['independence',7,4,'Independence Day','独立記念日'],['labor',9,0,'Labor Day','労働者の日',1,1],['columbus',10,0,'Columbus Day','コロンブスの日',2,1],['veterans',11,11,'Veterans Day','退役軍人の日'],['thanksgiving',11,0,'Thanksgiving Day','感謝祭',4,4],['christmas',12,25,'Christmas Day','クリスマス']
];
export function holidaysForYear(year,settings={},language='ja'){
 const result=new Map(),add=(day,name)=>{if(day.startsWith(String(year)+'-'))result.set(day,[...(result.get(day)||[]),name]);};
 if((settings.holidayRegion||'US')==='US')for(const y of [year-1,year,year+1])for(const [,month,fixed,en,ja,nth,weekday]of holidaySpecs){
  let d;if(fixed)d=new Date(Date.UTC(y,month-1,fixed,12));else if(nth===-1){d=new Date(Date.UTC(y,month,0,12));d.setUTCDate(d.getUTCDate()-(d.getUTCDay()-weekday+7)%7);}else{d=new Date(Date.UTC(y,month-1,1,12));d.setUTCDate(1+(weekday-d.getUTCDay()+7)%7+(nth-1)*7);}
  const day=iso(d),name=language==='en'?en:ja;add(day,name);if(fixed&&[0,6].includes(d.getUTCDay()))add(shift(day,d.getUTCDay()===6?-1:1),name+(language==='en'?' (Observed)':'（振替）'));
 }
 for(const h of settings.regionalHolidays||[])add(h.date,h.name);return result;
}

const JA_HOLIDAYS={"New Year's Day":'元日',"New Year’s Day":'元日','Martin Luther King Jr. Day':'キング牧師誕生日',"Washington's Birthday":'ワシントン誕生日','Memorial Day':'戦没者追悼記念日','Juneteenth National Independence Day':'ジューンティーンス','Independence Day':'独立記念日','Labor Day':'労働者の日','Columbus Day':'コロンブスの日','Veterans Day':'退役軍人の日','Thanksgiving Day':'感謝祭','Day After Thanksgiving':'感謝祭翌日','Friday After Thanksgiving':'感謝祭翌日','Christmas Eve':'クリスマスイブ','Christmas Day':'クリスマス','Day After Christmas':'クリスマス翌日','Christmas Holiday':'クリスマス休暇','Texas Independence Day':'テキサス独立記念日'};
export function storeHolidays(year,settings={},language='ja'){
 const result=holidaysForYear(year,settings,language),rows=REGION_DATA.holidays[settings.storeState]?.[String(year)];
 if(settings.holidayRegion==='none'||!rows)return result;
 for(const [suffix,index] of rows){const day=year+'-'+suffix,name=REGION_DATA.names[index],names=name.split('; ').map(n=>language==='ja'?(JA_HOLIDAYS[n]||n.replace(/ \(observed\)$/,'（振替）')):n);result.set(day,[...new Set([...(result.get(day)||[]),...names])]);}
 return result;
}

