 const order=()=>getState()?.orders.find(o=>o.id===context?.id);
 const editable=o=>getState()?.user?.role==='owner'&&o.paymentStatus==='paid'&&o.fulfillment!=='completed'&&!['pending','review_required','requires_action'].includes(o.refundStatus);
 const methodLabel=k=>({card:tx('カード','Card'),cash:tx('現金','Cash'),electronic:tx('電子マネー','Digital wallet'),other:tx('その他','Other')})[k]||k;
 function dateParts(value,wall=false){return transactionDateParts(value,{timeZone:getState()?.settings.timezone,language:getLang(),wall});}
 const paymentParts=o=>paymentTime(o,getState()?.settings,getLang());
