 const status=o=>o.fulfillment==='incoming'?tx('未処理・注文内容','Incoming orders'):o.fulfillment==='ready'?tx('お渡し待機中','Awaiting pickup'):tx('お渡し完了','Completed');
 function top(o,detail=false){
