  const times=`<dl class="context-times"><dt>${tx('注文時刻','Order time')}</dt><dd>${created.day}　${created.time}</dd><dt>${tx('受取予定','Pickup time')}</dt><dd>${pickup.day}　${formatTimeWindow(pickup.time,end)}</dd>${o.fulfillment==='completed'?`<dt>${tx('完了時刻','Completed at')}</dt><dd>${o.completedAt?dateParts(o.completedAt).time:'—'}</dd>`:''}</dl>`;
  if(!detail)return `<div class="compact-top">${identity}${times}</div>`;
