 }
 function quote(){return order()?.storeQuotes?.find(q=>q.id===context.quoteId);}
 function captureCheckout(){const method=$('#store-payment-method'),number=$('#receipt-number'),check=$('#store-payment-confirmed');if(method)context.payment.method=method.value;if(number)context.payment.receiptNumber=number.value;if(check)context.payment.confirmed=check.checked;}
