/* Amounts are integer cents. Online charge data never changes in this module. */
import {isOrderActionable} from './payment-guards.mjs';
const clone=v=>structuredClone(v);
export const COMMERCE_KINDS=['order.exchange.received','order.exchange','order.quote','order.storePurchase','order.quoteCancel'];
