export class CommerceError extends Error{constructor(message,status=400,code='validation_error'){super(message);Object.assign(this,{status,code});}}
const fail=(m,s=400,c='validation_error')=>{throw new CommerceError(m,s,c);};
const int=(v,a,b)=>{if(!Number.isSafeInteger(v)||v<a||v>b)fail('入力の形式または文字数を確認してください。');return v;};
