}
export function estimateFee(amount,config){return config===null?null:Math.floor((amount*config.rateBps+5000)/10000)+config.fixedCents;}
export function snapshotOnlineFees(state,config){for(const o of state.orders)if(!Object.hasOwn(o,'onlineFeeEstimate'))o.onlineFeeEstimate={config:clone(config.online),cents:estimateFee(o.amountCents,config.online)};}
export const handoffItems=o=>clone(o.handoffItems||o.items.map((i,n)=>({...i,lineId:'base:'+n})));
