  }else{
   const receipt=(o.exchangeReceipts||[]).find(r=>r.id===p.receiptId&&Object.entries(proposal).every(([k,v])=>r[k]===v)&&!r.exchangeId);
   if(difference>0&&!receipt)fail('同じ交換内容の差額受領確認を保存してください。',409,'exchange_receipt_required');
