   items.push(replacement);o.handoffItems=items;const event={id,operationId:operation,source:{...original,quantity:qty},replacement:clone(replacement),differenceCents:difference,at,actorId:actor.id};if(receipt){receipt.exchangeId=id;event.receiptId=receipt.id;}(o.exchanges||=[]).push(event);result={ok:true,exchangeId:id};
  }
 }else if(kind==='order.quote'){
  assertHandoffAllowed(o);if(!Array.isArray(p.lines)||!p.lines.length||p.lines.length>100)fail('追加する商品を確認してください。');const seen=new Set(),products=[];
  for(const line of p.lines){if(!obj(line))fail('追加する商品を確認してください。');const product=find(state.products,line.productId);if(seen.has(product.id))fail('同じ商品は個数をまとめてください。');seen.add(product.id);if(product.soldOut)fail(product.name+'は売り切れです。',409);products.push({productId:product.id,name:product.name,quantity:int(line.quantity,1,999),unitCents:product.priceCents});}
