 }else{
  const q=find(o.storeQuotes||[],p.quoteId);if(q.status!=='open')fail('この店頭会計はすでに処理されています。',409,'quote_closed');
  if(kind==='order.quoteCancel'){if(p.confirmedUnpaid!==true)fail('既存レジで未会計であることを確認してください。');Object.assign(q,{status:'cancelled',cancelledAt:at,cancelledBy:actor.id});result={ok:true,quoteId:q.id};}
