  const constraints=track.getConstraints?.()||{};
  await track.applyConstraints({...constraints,advanced:[...(constraints.advanced||[]),{focusMode:'continuous'}]});
  return track.getSettings?.().focusMode==='continuous';
 }catch{return false;}
}
// Only browser capability and the detector are reused, never QR results.
const qrDetectors=new WeakMap();
async function qrDetector(Detector){
 if(!qrDetectors.has(Detector)){
  const pending=(async()=>{
   const formats=await Detector.getSupportedFormats?.();
   return !formats||formats.includes('qr_code')?new Detector({formats:['qr_code']}):null;
  })();
  qrDetectors.set(Detector,pending);
  // A transient initialization failure may recover on the next frame.
  pending.catch(()=>{if(qrDetectors.get(Detector)===pending)qrDetectors.delete(Detector);});
 }
