import {lookupFeedback,returnFeedback,pickupFeedback} from './feedback-views.mjs';
import {createStoreUI} from './store-ui.mjs';

export const DISPLAY_STATES=Object.freeze([
 {id:'lookup-network',group:'注文の照合',label:'通信失敗',kind:'lookup',status:503},
 {id:'lookup-denied',group:'注文の照合',label:'操作権限不足',kind:'lookup',status:403},
 {id:'lookup-mismatch',group:'注文の照合',label:'注文番号の不一致',kind:'lookup',status:404},
 {id:'lookup-unavailable',group:'注文の照合',label:'お渡し不可',kind:'lookup',status:409},
 {id:'return-waiting',group:'戻す',label:'処理状況の確認中',kind:'return',phase:'waiting'},
 {id:'return-unknown',group:'戻す',label:'処理結果未確認',kind:'return',phase:'unknown'},
 {id:'return-conflict',group:'戻す',label:'別の操作による更新',kind:'return',phase:'notice'},
 {id:'return-completed',group:'戻す',label:'他のスタッフがお渡し完了',kind:'return',phase:'completed'},
 {id:'pickup-waiting',group:'受渡し・準備',label:'お渡し完了の確認中',kind:'pickup',phase:'waiting'},
 {id:'pickup-unknown',group:'受渡し・準備',label:'お渡し完了の結果未確認',kind:'pickup',type:'order.handoff.complete'},
 {id:'staff-unknown',group:'受渡し・準備',label:'担当者保存の結果未確認',kind:'pickup',type:'order.handoff.assign'},
 {id:'packing-unknown',group:'受渡し・準備',label:'準備完了の結果未確認',kind:'pickup',type:'order.packing.confirm'},
 {id:'exchange-unknown',group:'交換',label:'交換の結果未確認',kind:'pickup',type:'order.exchange'},
 {id:'receipt-unknown',group:'交換',label:'差額受領確認の結果未確認',kind:'pickup',type:'order.exchange.received'},
 {id:'store-error',group:'店舗設定',label:'保存失敗',kind:'store',status:422},
 {id:'store-unknown',group:'店舗設定',label:'保存結果未確認',kind:'store',status:503},
]);

export function reviewFeedback(state,{identity,orders,customerName,esc,btn}){
 if(state.kind==='lookup')return lookupFeedback({error:{status:state.status},lastLookup:{number:String(orders[0]?.number||'6001')},orders,customerName,esc,btn});
 if(state.kind==='return')return returnFeedback(state.phase,{identity,message:'別の操作で更新されています。最新の内容を確認してください。',staff:'Taylor Reed',esc});
 if(state.kind==='pickup')return pickupFeedback(state.phase||'unknown',{identity,type:state.type,preparation:state.type==='order.packing.confirm',handoff:state.type==='order.handoff.complete'||state.type==='order.handoff.assign'});
 return null;
}

/** Display-only boundary. No transport, storage, timers, or live controllers. */
export function createDisplayReview({available,getState,openView,onEnter,onExit,esc,btn,icon,money,customerName,document:doc=globalThis.document,window:win=globalThis.window}){
 let active=false,rail=null,selected=DISPLAY_STATES[0],store=null,generation=0;
 const root=()=>doc.querySelector('#overlay-root .dialog');
 function present(view){
  openView(view);const dialog=root();if(!dialog)return;
  dialog.dataset.uiReview=selected.id;dialog.setAttribute('aria-modal','false');
  if(view.options?.disableClose)dialog.querySelector('.dialog-close').disabled=true;
 }
 function resetStore(){store?.reset();store=null;}
 async function show(id){
  if(!active)return;selected=DISPLAY_STATES.find(s=>s.id===id)||DISPLAY_STATES[0];
  const ticket=++generation;resetStore();rail.querySelector('select').value=selected.id;
  rail.querySelector('[data-review-current]').textContent=selected.group+' · '+selected.label;
  const source=getState(),order=source.orders?.[0],identity=order?`<p class="qr-order-identity">注文番号 ${esc(order.number)}　${esc(customerName(order))}</p>`:'';
  if(selected.kind!=='store'){
   present(reviewFeedback(selected,{identity,orders:source.orders||[],customerName,esc,btn}));return;
  }
  // The full current store form renders against an isolated in-memory snapshot.
  // Its settings writer receives only this local stub, never the app API.
  let state=structuredClone(source);const status=selected.status;
  store=createStoreUI({getState:()=>state,setState:next=>{state=next;},getRoot:()=>root()||doc.createDocumentFragment(),
   api:async(_path,options={})=>{if((options.method||'GET')!=='GET')throw Object.assign(new Error(status===422?'入力内容を保存できませんでした。内容を確認して、もう一度お試しください。':'保存結果を確認できません。接続後に保存内容を確認してください。'),{status});return structuredClone(state);},
   renderShell:(title,body)=>present({title,body,options:{className:'ui-review-store',scanShortcut:false,autoFocus:false,orderFlow:false}}),
   openModal:(title,body,options)=>present({title,body,options}),closeModal:stop,icon,esc,t:v=>v,getLang:()=> 'ja',loadIntegrations:()=>{const node=root()?.querySelector('#integration-status');if(node)node.textContent='接続状況の表示確認';}});
  store.render();const current=store;await current.savePatch({name:state.settings.name});
  if(ticket!==generation)return;
  const panel=root()?.querySelector('.store-calendar-panel');if(panel)panel.scrollTop=panel.scrollHeight-panel.clientHeight;
 }
 function start(id){
  if(active||!available())return false;
