// A failed/canceled refund is not a successful refund. Unknown financial states
// are excluded until the caller has reconciled them with the server.
const countableRefundStates = new Set(['', 'failed', 'canceled']);

function userMatches(user, tenantId, requireTenant = false) {
  return record(user) && identifier(user.id) && orderRoles.has(user.role)
    && (!requireTenant || identifier(user.tenant_id))
    && (!own(user, 'tenant_id') || user.tenant_id === tenantId);
}

function orderBelongsTo(order, tenantId) {
