  // If a future DTO supplies one, an explicit mismatch must never be counted.
  for (const key of ['tenantId', 'tenant_id']) {
    if (own(order, key) && order[key] !== tenantId) return false;
  }
  if (own(order, 'tenant')) {
    const id = record(order.tenant) ? order.tenant.id : order.tenant;
    if (id !== tenantId) return false;
  }
