  if (order.paymentStatus !== 'paid' || order.fulfillment !== 'incoming') return false;
  if (order.refundStatus != null && !countableRefundStates.has(order.refundStatus)) return false;
  // A partial/full refund with a lagging paymentStatus is not an actionable order.
  return order.refundedCents == null || order.refundedCents === 0;
