export function countIncomingOrders(state, context = {}) {
  if (!record(state) || !record(context) || !record(state.tenant)
    || !identifier(state.tenant.id) || !Array.isArray(state.orders)
    || !record(state.tenant.features) || state.tenant.features.orders !== true) return 0;

  const tenantId = state.tenant.id;
  if (own(context, 'tenantId') && context.tenantId !== tenantId) return 0;
