  if (own(context, 'session')) {
    if (!record(context.session)) return 0;
    user = context.session.user;
    if (!userMatches(user, tenantId, true)) return 0;
  } else if (own(context, 'user')) {
    user = context.user;
    if (!userMatches(user, tenantId, true)) return 0;
  } else {
    user = state.user;
    if (!userMatches(user, tenantId)) return 0;
