/* Shared financial facts. No commerce/refund dependency or browser globals. */
export function financialStatus(order){
 if(order.paymentStatus==='refunded')return 'succeeded';
 const refunded=order.refundedCents??0;
 if(!Number.isSafeInteger(refunded)||refunded!==0)return 'review';
 const status=order.refundStatus;
 if(status===null||status===undefined||status==='')return null;
 if(typeof status!=='string')return 'review';
