export function timeZoneLabel(timeZone){
 if(typeof timeZone!=='string'||!timeZone)return '—';
 try{dateFormatter('en-US',{timeZone});return timeZone;}catch{return '—';}
}

export function transactionDateParts(value,{timeZone,language='en',wall=false}={}){
 if(!validISO(value))return EMPTY();
 if(!OFFSET.test(value)){
