import {handoffItems, assertHandoffAllowed} from './commerce.mjs';
import {isOrderActionable} from './payment-guards.mjs';
export const PICKUP_KINDS = ['order.packing.confirm', 'order.handoff.assign', 'order.handoff.complete'];
export const itemsSignature = o => JSON.stringify(handoffItems(o).map(i => [i.lineId, i.productId ?? null, i.name, i.quantity, i.unitCents]));
export function packingValid(o) {
  return !!o.packing?.staffId && o.packing.itemsSignature === itemsSignature(o)
    && JSON.stringify([...o.packing.checkedLineIds].sort()) === JSON.stringify(handoffItems(o).map(i=>i.lineId).sort());
}
export function recordWork(o,work,staff,actor,at,operationId){
  const records=o.workLog??=[];
  if(!records.some(r=>r.operationId===operationId&&r.work===work))records.push({work,staffId:staff.staffId??staff.id,staffName:staff.staffName??staff.name??'',actorId:actor.id,completedAt:at,operationId});
}
export function returnPreparation(o,actor,at,operationId){
  if(o.preparedAt)recordWork(o,'preparation',o.packing||{},actor,o.preparedAt,o.packing?.operationId||'legacy-preparation:'+o.preparedAt);
  for(const record of o.workLog||[])if(record.work==='preparation'&&!record.revertedAt)Object.assign(record,{revertedAt:at,returnOperationId:operationId});
}
// Legacy records stay readable without manufacturing a staff member or time.
export function workRecords(o){
  const records=(o.workLog||[]).map(r=>({...r}));
  for(const [work,at,staff] of [['preparation',o.preparedAt,o.packing],['handoff',o.completedAt,o.completedBy]]){
    if(at&&!records.some(r=>r.work===work&&r.completedAt===at&&!r.revertedAt))records.push({work,completedAt:at,staffId:staff?.staffId,staffName:staff?.staffName||''});
    if(!records.some(r=>r.work===work))records.push({work,completedAt:null,staffName:''});
  }
  return records;
}
export function applyPickup(s, kind, p, actor, at, operationId, fail) {
  const reject=(message, code='order_unavailable')=>fail(message,409,code);
  const o=s.orders.find(o=>o.id===p.id);
  if(!o)reject('注文が見つかりません。','order_not_found');
  if(!isOrderActionable(o))reject('取消・返金・決済状態を確認してください。');
  assertHandoffAllowed(o);
  if(o.fulfillment==='completed')reject('この注文はすでにお渡し完了です。一覧をご確認ください。','already_completed');
  const signature=itemsSignature(o);
  if(p.itemsSignature!==signature)reject('注文内容が更新されています。最新の内容をご確認ください。','items_changed');
  const staff=s.staffRoster?.find(v=>v.id===p.staffId&&v.active===true);
  if(!staff)reject('有効な担当者を選択してください。','staff_required');
  if(kind==='order.packing.confirm') {
    if(Object.hasOwn(p,'prepare')&&typeof p.prepare!=='boolean')reject('準備完了の指定を確認してください。','invalid_preparation');
    if(o.fulfillment!=='incoming'||!Array.isArray(p.checkedLineIds)||JSON.stringify([...p.checkedLineIds].sort())!==JSON.stringify(handoffItems(o).map(i=>i.lineId).sort()))reject('すべての商品と担当者を確認してください。','packing_required');
    o.packing={itemsSignature:signature,checkedLineIds:p.checkedLineIds,staffId:staff.id,staffName:staff.name,confirmedAt:at,operationId};
    if(p.prepare===true){o.fulfillment='ready';o.preparedAt=at;if(o.handoff?.reviewRequired)delete o.handoff;recordWork(o,'preparation',staff,actor,at,operationId);}
  } else if(kind==='order.handoff.assign') {
    if(o.handoff?.reviewRequired)reject('商品準備の確認が必要です。','preparation_required');
    if(o.fulfillment!=='ready'||!packingValid(o))reject('準備状況と注文内容を確認してください。','preparation_required');
    if(o.handoff&&(o.handoff.staffId!==staff.id||o.handoff.actorId!==actor.id))reject('他のスタッフが対応中です。現場の状況をご確認ください。','handoff_conflict');
    o.handoff={staffId:staff.id,staffName:staff.name,actorId:actor.id,assignedAt:at,assignmentOperationId:operationId,itemsSignature:signature};
  } else if(kind==='order.handoff.complete') {
    const h=o.handoff;
    if(h?.reviewRequired||o.fulfillment!=='ready'||!packingValid(o)||h?.staffId!==staff.id||h?.actorId!==actor.id||h?.assignmentOperationId!==p.assignmentOperationId||h?.itemsSignature!==signature)reject('担当者と最新のお渡し状況をご確認ください。','handoff_conflict');
    o.fulfillment='completed';o.completedAt=at;o.completedBy={staffId:staff.id,staffName:staff.name,actorId:actor.id,operationId};
    recordWork(o,'handoff',staff,actor,at,operationId);
  }
  return o;
}

