// Visual feedback only. Business actions remain on their existing click handlers.
import {INTERACTIVE_CONTROLS,isInteractionBlocked} from './interaction-controls.mjs';
const PRESSED = 'ops-pressed', MANAGED = 'ops-touch-managed';
const MOVE_SLOP_SQUARED = 8 * 8;

export function installPressFeedback(doc = document) {
  const win = doc.defaultView, presses = new Map(), touches = new Set();
  const controlFor = target => {
    if (!doc.documentElement.classList.contains('cms-display') ||
        !doc.documentElement.classList.contains('ops-foundation')) return null;
    const control = target?.closest?.(INTERACTIVE_CONTROLS);
    return control?.closest('#app,#overlay-root,#boot-screen,.ui-review-rail') ? control : null;
  };
  const release = pointerId => {
    const press = presses.get(pointerId);
    if (press) {
      if (press.frame !== null) win.cancelAnimationFrame(press.frame);
      press.control.classList.remove(PRESSED);
    }
    presses.delete(pointerId);
  };
  const releaseAll = () => { for (const id of presses.keys()) release(id); };
  const reset = () => { releaseAll(); touches.clear(); };
  const onDown = event => {
    const control = controlFor(event.target);
    if (event.pointerType !== 'touch' && event.pointerType !== 'pen') {
      releaseAll();
      control?.classList.remove(MANAGED);
      return;
    }
    touches.add(event.pointerId);
    // Keep Chrome's delayed :active from replaying after release or cancellation.
    control?.classList.add(MANAGED);
    if (touches.size > 1 || event.isPrimary === false) { releaseAll(); return; }
    if (event.button !== 0 || isInteractionBlocked(control)) return;
    releaseAll();
    const press = {control, x: event.clientX, y: event.clientY, frame: null, presented: false, released: false};
    presses.set(event.pointerId, press);
    control.classList.add(PRESSED);
    // Start immediately. A sub-frame tap still gets one rendering opportunity;
    // neither its native click nor any business operation waits for these frames.
    press.frame = win.requestAnimationFrame(() => {
      press.frame = win.requestAnimationFrame(() => {
        press.frame = null;
        press.presented = true;
        if (press.released) release(event.pointerId);
      });
    });
  };
  const onMove = event => {
    const press = presses.get(event.pointerId);
    if (!press) return;
    const dx = event.clientX - press.x, dy = event.clientY - press.y;
    if (dx * dx + dy * dy > MOVE_SLOP_SQUARED) release(event.pointerId);
  };
  const onUp = event => {
    touches.delete(event.pointerId);
    const press = presses.get(event.pointerId);
    if (!press) return;
    press.released = true;
    if (press.presented) release(event.pointerId);
  };
  const onCancel = event => { release(event.pointerId); touches.delete(event.pointerId); };
  // Touch's implicit capture ends after pointerup. Do not erase its pending frame.
  const onLostCapture = event => {
    if (!presses.get(event.pointerId)?.released) onCancel(event);
  };
  const onKey = event => {
    releaseAll();
    controlFor(event.target)?.classList.remove(MANAGED);
  };
  const onVisibility = () => { if (doc.hidden) reset(); };
  const passiveCapture = {capture: true, passive: true};
  const documentEvents = {pointerdown: onDown, pointermove: onMove, pointerup: onUp,
    pointercancel: onCancel, lostpointercapture: onLostCapture, scroll: releaseAll, keydown: onKey,
    visibilitychange: onVisibility};
  const windowEvents = {blur: reset, pagehide: reset, hashchange: reset};
  for (const [name, handler] of Object.entries(documentEvents)) doc.addEventListener(name, handler, passiveCapture);
  for (const [name, handler] of Object.entries(windowEvents)) win.addEventListener(name, handler);
  return () => {
    reset();
    for (const [name, handler] of Object.entries(documentEvents)) doc.removeEventListener(name, handler, true);
    for (const [name, handler] of Object.entries(windowEvents)) win.removeEventListener(name, handler);
  };
}

