// Reuse confirmed list rows only. Data writes and revision checks stay with the
// caller; this module never performs an optimistic move or dispatches a command.
import {syncChildOrder} from './dom-updates.mjs';
const snapshots=new WeakMap();
// Media URLs can be large data strings. Keep primitives directly instead of
// allocating a second JSON string for every image on every reorder.
const field=value=>value!==null&&typeof value==='object'?JSON.stringify(value):value;
function content(product){
