 // fall back to the normal renderer instead of leaving an outdated row visible.
 if(products.some(p=>{
  const node=byId.get(p.id),controls=saved.controls.get(node);
  return !node||!sameContent(saved.products.get(p.id),p)||!controls||
   [controls.up,controls.down,controls.toggle].some(control=>!control||!node.contains(control));
 }))return false;
 syncChildOrder(body,products.map(p=>byId.get(p.id)));
 for(const [i,p]of products.entries()){
  const node=byId.get(p.id);
  const controls=saved.controls.get(node);
  for(const [button,disabled]of [[controls.up,i===0],[controls.down,i===products.length-1]]){
   if(button&&button.disabled!==disabled)button.disabled=disabled;
  }
  const toggle=controls.toggle,checked=String(p.soldOut);
  if(toggle&&toggle.getAttribute('aria-checked')!==checked)toggle.setAttribute('aria-checked',checked);
