// Candidate geometry is separate from successful decoding. Tuning remains Q-05.
export const QR_ATTEMPT_MS=4000;
export function candidateState(boxes,size=400){
  boxes=boxes.filter(b=>b&&[b.x,b.y,b.width,b.height].every(Number.isFinite)&&b.width>=24&&b.height>=24&&b.width/b.height>=.5&&b.width/b.height<=2);
  if(boxes.length>1)return {kind:'multiple'};
  const b=boxes[0],margin=4;
  if(!b)return {kind:'undetected'};
  if(b.x<margin||b.y<margin||b.x+b.width>size-margin||b.y+b.height>size-margin)return {kind:'outside'};
  return {kind:'single',box:b};
}
export function stableCandidate(before,after){
  if(!before||!after)return false;
  const span=Math.max(before.width,before.height,after.width,after.height);
  return Math.abs(before.x-after.x)<span*.12&&Math.abs(before.y-after.y)<span*.12&&Math.abs(before.width-after.width)<span*.15&&Math.abs(before.height-after.height)<span*.15;
}
export function createAttemptClock({duration=QR_ATTEMPT_MS,now=()=>performance.now()}={}){
  let failed=0,since=null,previous=null,stableSince=null;
  return {
    sample(candidate,visible=true){
      const time=now();
      if(!visible||candidate.kind!=='single'){since=null;stableSince=null;previous=null;return {blue:false,expired:false,failed};}
      if(!stableCandidate(previous,candidate.box)){since=null;stableSince=time;}
      previous=candidate.box;
      const blue=time-(stableSince??time)>=150;
      if(!blue)return {blue:false,expired:false,failed};
      since??=time;
      if(time-since>=duration){failed++;since=null;stableSince=null;previous=null;return {blue:true,expired:true,failed};}
      return {blue:true,expired:false,failed};
    },
    reset(){since=null;stableSince=null;previous=null;},
    failures(){return failed;},
  };
}

