  if(operation.referenceVerified&&operation.referenceId!==order.id)return {operationId,definitive:false,status:'unknown'};
  const result=await api('/api/orders/'+encodeURIComponent(order.id)+'/refund/operations/'+encodeURIComponent(operationId));
  if(result.operationId!==operationId||!['succeeded','failed'].includes(result.financialStatus))return {operationId,definitive:false,status:'unknown'};
