  if(checking||disposed||!controller.getStatus().online||!context().user)return false;
  checking=true;let resolved=false;
  try{
   for(const operation of controller.getStatus().unknownOperations){
    if(operation.operationId)try{let receipt;const ok=await controller.recoverOperation(operation.operationId,async op=>{receipt=await lookup(op);return receipt;});if(ok){resolved=true;onResolved(receipt,operation);}}catch{/* Keep the uncertain operation; never replace a failed lookup by success. */}
