export function executeDemoRefund(state,orderId,{operationId,expectedRevision=null,requestId=null,reserve=null,at=new Date().toISOString()}={}){
 const order=orderFor(state,orderId),explicit=operationId!==undefined&&operationId!==null;
 operationId=explicit?operationId:`refund:${state.tenant.id}:${orderId}`;
 if(expectedRevision!==null&&(!Number.isInteger(expectedRevision)||expectedRevision<1))reject('版番号の形式を確認してください。','invalid_revision',400);
 const prior=getRefundOperation(state,operationId,orderId);
 if(prior&&prior.requestId!==requestId)reject('操作IDの申請対象が一致しません。','operation_conflict');
