 if(prior){if(!explicit)reject('返金サービス側の状態を確認してください。');return refundResult(order,true);}
 if(expectedRevision!==null&&expectedRevision!==state.revision)reject('別の操作で更新されています。最新の内容を確認してください。','revision_conflict');
