/* Called by the existing transport and by the approval adapter. The storage
 * transaction owns atomicity/rollback, including the reserve callback. */
export function createDemoRefundExecutor({storage,now=()=>new Date(),getUser}){
 return async({tenantId,orderId,expectedRevision=null,operationId,refundRequestId=null,reserve=null})=>{
  const user=getUser();
  if(!user||user.tenant_id!==tenantId||user.role!=='owner')reject('この操作には店主の権限が必要です。','permission_denied',403);
  return storage.mutate(tenantId,state=>{
   if(!state.tenant.features.sales)reject('この店舗ではこの機能を利用できません。','feature_disabled',403);
   const before=JSON.stringify(state),result=executeDemoRefund(state,orderId,{operationId,expectedRevision,requestId:refundRequestId,reserve,at:now().toISOString()});
   if(JSON.stringify(state)!==before){state.audit.push({id:'aud_'+crypto.randomUUID(),at:now().toISOString(),actor:user.id,action:'order.refund.succeeded',target:orderId});state.audit=state.audit.slice(-1000);state.revision++;}
