}

export function demoRefundOperationView(state,orderId,operationId,at=new Date().toISOString()){
 const order=orderFor(state,orderId),op=getRefundOperation(state,operationId,orderId);
 if(!op||op.tenantId!==state.tenant.id)reject('返金操作が見つかりません。','refund_operation_not_found',404);
 const recovery={canCheck:true,canResume:false,reason:'provider_result_known',nextAction:'check',checked:op.lastProviderCheckSucceeded===true};
 const status=financialStatus(order),params=op.providerParams;
 if(['succeeded','failed'].includes(status))Object.assign(recovery,{canCheck:false,reason:'financial_terminal',nextAction:'none'});
 else if(op.dispatchVersion!==1||op.orderId!==orderId||op.paymentReference!==order.paymentReference||op.amountCents!==order.amountCents||op.idempotencyKey!==`refund:${state.tenant.id}:${orderId}`||typeof op.providerAccount!=='string'||params?.payment_intent!==order.paymentReference||params?.amount!==order.amountCents||params?.['metadata[tenant_id]']!==state.tenant.id||params?.['metadata[order_id]']!==orderId||!order.paymentReference.startsWith('demo_'))Object.assign(recovery,{canCheck:false,reason:'missing_or_changed_snapshot',nextAction:'manual_review'});
 else if(op.workLeaseUntil>new Date(at).getTime()/1000)Object.assign(recovery,{canCheck:false,reason:'operation_in_progress',nextAction:'wait'});
 else if(order.refundedCents)Object.assign(recovery,{reason:'partial_refund',nextAction:'manual_review'});
 else if(order.refundId)Object.assign(recovery,{reason:'provider_result_known',nextAction:'check'});
 else if(op.dispatchAttempts===0&&op.firstDispatchAt===null)Object.assign(recovery,{canResume:true,reason:'reserved_not_dispatched',nextAction:'resume'});
 else{
  const age=new Date(at)-new Date(op.firstDispatchAt);
  if(!Number.isFinite(age)||age<0)Object.assign(recovery,{reason:'dispatch_time_untrusted',nextAction:'manual_review'});
  else if(age>=23*3600*1000)Object.assign(recovery,{reason:'replay_window_expired',nextAction:'manual_review'});
  else Object.assign(recovery,{canResume:true,reason:'same_key_replay_window',nextAction:'resume'});
 }
 return {...refundResult(order,true),revision:state.revision,recovery};
}

/* Fictional browser-local counterpart. It never calls Stripe or another
 * browser. Explicit resume completes the same simulated operation once. */
export function createDemoRefundRecoveryExecutor({storage,now=()=>new Date(),getUser}){
 return async({tenantId,orderId,operationId,expectedRevision,mode,confirmResume})=>{
  const user=getUser();if(!user||user.tenant_id!==tenantId||user.role!=='owner')reject('この操作には店主の権限が必要です。','permission_denied',403);
  if(!Number.isInteger(expectedRevision)||expectedRevision<1)reject('版番号の形式を確認してください。','invalid_revision',400);
  if(!['check','resume'].includes(mode)||mode==='resume'&&confirmResume!==true)reject('返金の再確認方法を確認してください。','refund_recovery_confirmation',400);
  return storage.mutate(tenantId,state=>{
   if(!state.tenant.features.sales)reject('この店舗ではこの機能を利用できません。','feature_disabled',403);
   if(state.revision!==expectedRevision)reject('別の操作で更新されています。最新の内容を確認してください。','revision_conflict');
   const at=now().toISOString(),view=demoRefundOperationView(state,orderId,operationId,at);
   if(['succeeded','failed'].includes(view.financialStatus))return view;
   if(view.recovery.reason==='operation_in_progress')reject('この返金操作を確認中です。少し待って再確認してください。','refund_operation_busy');
