    Object.assign(order,{paymentStatus:'refunded',refundStatus:'succeeded',refundedCents:order.amountCents,refundId:'demo_refund_'+orderId});
   }else order.refundStatus='review_required';
   op.financialStatus=financialStatus(order);op.updatedAt=at;op.lastProviderCheckSucceeded=view.recovery.canCheck;
   syncRefundRequests(state);state.audit.push({id:'aud_'+crypto.randomUUID(),at,actor:user.id,action:'order.refund.demo-recovery.'+mode,target:orderId});state.audit=state.audit.slice(-1000);state.revision++;
   return demoRefundOperationView(state,orderId,operationId,at);
  });
 };
}

