/* Request/approval parity for the browser-local demo, never a real refund. */
const view=(state,item,customer=false)=>{
 const order=state.orders.find(o=>o.id===item.orderId);
 if(!order)throw new Error('Refund request order is missing.');
 const keys=['id','orderId','requestedAt','amountCents','currency','status','approvedAt',...(!customer?['customerId','approvedBy','approvalOperationId']:[])];
 const result=Object.fromEntries(keys.map(k=>[k,item[k]??null]));
 return {...result,orderNumber:order.number,financialStatus:financialStatus(order)};
};
export function financialStatus(order){
 if(order.paymentStatus==='refunded')return 'succeeded';
 if(order.refundedCents)return 'review';
 const status=order.refundStatus;
 if(status===null||status===undefined||status==='')return null;
 if(typeof status!=='string')return 'review';
 const statuses={pending:'processing',review_required:'review',requires_action:'review',succeeded:'review',failed:'failed',canceled:'failed'};
 return Object.hasOwn(statuses,status)?statuses[status]:'review';
}
const op=(value,fail)=>{if(typeof value!=='string'||!/^[A-Za-z0-9_.:-]{8,120}$/.test(value))fail('操作番号を確認してください。',400,'operation_id_required');return value;};
export function reserveDemoApproval(state,order,{requestId,operationId,actorId,at,fail}){
 const item=(state.refundRequests||[]).find(r=>r.id===requestId);
 if(!item)fail('返金申請が見つかりません。',404,'not_found');
 if((state.refundRequests||[]).some(r=>r.id!==requestId&&r.approvalOperationId===operationId))fail('同じ操作番号が別の申請に使われています。',409,'operation_conflict');
 if(item.status!=='requested')fail('この申請は承認できません。',409,'refund_request_not_approvable');
 if(item.orderId!==order.id||item.customerId!==order.customerId||item.amountCents!==order.amountCents||order.paymentStatus!=='paid'||financialStatus(order)!==null)fail('決済・返金状態を確認してください。',409,'order_unavailable');
 Object.assign(item,{status:'approved',approvedAt:at,approvedBy:actorId,approvalOperationId:operationId});
 return item;
}
export async function handleDemoRefundRequest({path,method,headers,body,user,csrf,storage,seed,now,uid,fail,response,executeRefund,allowLegacyReceipt=()=>false,origin=globalThis.location?.origin||'https://demo.invalid'}){
