 if(method==='POST'&&h.get('X-CSRF-Token')!==csrf)fail('画面を再読み込みして、もう一度お試しください。',403,'csrf_failed');
 if(method==='POST'&&h.get('Origin')&&h.get('Origin')!==origin)fail('この接続元からは操作できません。',403,'origin_failed');
