  await storage.mutate(tenant,state=>{
   if(!state.tenant.features.sales)fail('この店舗ではこの機能を利用できません。',403,'feature_disabled');
   const order=state.orders.find(o=>o.id===create[1]&&o.qrToken===token);
   if(!order)fail('注文が見つかりません。',404,'not_found');
