 if(!user)fail('ログインしてください。',401,'unauthenticated');
 if(user.role!=='owner')fail('この操作には店主の権限が必要です。',403,'permission_denied');
 const state=await storage.get(user.tenant_id);
 if(!state.tenant.features.sales)fail('この店舗ではこの機能を利用できません。',403,'feature_disabled');
