   if(fresh.tenant.id!==user.tenant_id||!fresh.tenant.features.sales)fail('この店舗ではこの機能を利用できません。',403,'feature_disabled');
   reserveDemoApproval(fresh,order,{requestId:item.id,operationId,actorId:user.id,at:now().toISOString(),fail});
   fresh.audit.push({id:uid('aud'),at:now().toISOString(),actor:user.id,action:'refund_request.approved',target:item.id});fresh.audit=fresh.audit.slice(-1000);
  } });
