  ['none','not_started'].includes(financial)&&canonicalFinancialStatus(order)===null&&Number.isInteger(request.amountCents)&&
  (!order.refundStatus||['none','not_started'].includes(order.refundStatus))&&
  request.amountCents>0&&request.amountCents===order.amountCents&&
