 function summary(ctx){return `<div class="refund-summary"><div class="refund-order"><strong>#${esc(ctx.order.number)}</strong><span>${esc(person(ctx.order,ctx.source))}</span></div><dl><div><dt>${esc(tx('申請日時'))}</dt><dd>${esc(date(ctx.request.requestedAt,ctx.source))}</dd></div><div><dt>${esc(tx('対象オンライン金額'))}</dt><dd class="refund-amount">${money(ctx.request.amountCents)}</dd></div><div><dt>${esc(tx('申請状態'))}</dt><dd>${esc(requestStatus(ctx.request))}</dd></div><div><dt>${esc(tx('返金状態'))}</dt><dd>${financialHTML(ctx.request,ctx.order)}</dd></div></dl></div>`;}
