 }
 async function reviewOperation(orderId,id){
  const key=context(),marker=query('.refund-content')||query('.refund-dialog');
  if(state()?.user?.role!=='owner'||typeof id!=='string'||!/^[A-Za-z0-9_.:-]{1,120}$/.test(id))throw new Error(tx('店主のみ承認できます'));
  const data=await api('/api/orders/'+encodeURIComponent(orderId)+'/refund/operations/'+encodeURIComponent(id));
