/* Serialize complete settings writes, while changing only the selected fields. */
const copy=value=>structuredClone(value);
const equal=(a,b)=>JSON.stringify(a)===JSON.stringify(b);
export function createSettingsWriter({getState,setState,read,write,onStatus=()=>{}}){
 let tail=Promise.resolve(),last=null,failed=null,uncertain=false,generation=0,pending=0;
 const defaults={contentLanguageMode:'auto',contentLocale:'en-US',paymentFees:{online:null,store:{card:null,cash:{rateBps:0,fixedCents:0},electronic:null,other:null}},closureRules:[],openDates:[],closedDates:[],storeState:'',storeRegion:'',closureNote:'',holidayRegion:'US'};
 const enqueue=(task,allowFailed=false)=>{pending++;if(!failed)onStatus('saving');const epoch=generation,tenant=getState().tenant.id;
  const result=tail.then(async()=>{
   if(epoch!==generation||getState().tenant.id!==tenant)throw new Error('店舗が変更されました。');
   if(failed&&!allowFailed)throw new Error('先の保存を確認してから、もう一度操作してください。');
   return task(tenant,epoch);
  });tail=result.catch(()=>{});return result.finally(()=>{pending--;});};
 async function commit(patch,label,tenant,epoch,undo=false){
  const state=getState(),delta=typeof patch==='function'?patch(copy(state.settings)):copy(patch),keys=Object.keys(delta);
  const before=Object.fromEntries(keys.map(k=>[k,copy(state.settings[k]??defaults[k]??'')]));
  const payload={...copy(state.settings),...delta};let written=false;
  try{
   await write(payload,state.revision);written=true;
   const next=await read();if(epoch!==generation||next.tenant.id!==tenant||getState().tenant.id!==tenant)throw new Error('店舗が変更されました。');
   setState(next);last=undo?null:{before,after:Object.fromEntries(keys.map(k=>[k,copy(next.settings[k]??defaults[k]??'')])),label};failed=null;uncertain=false;onStatus('saved',label);return next;
  }catch(error){
   if(epoch===generation){failed={patch:delta,label,before};uncertain=written||!error.status||error.status>=500;onStatus(uncertain?'uncertain':'error',error.message);}
   throw error;
  }
 }
