  save(patch,label='変更を保存しました'){return enqueue((tenant,epoch)=>{if(failed){if(!uncertain){const delta=typeof patch==='function'?patch(copy(getState().settings)):copy(patch);for(const key of Object.keys(delta))if(!Object.hasOwn(failed.before,key))failed.before[key]=copy(getState().settings[key]??defaults[key]??'');failed.patch={...failed.patch,...delta};failed.label=label;onStatus('error','未保存の変更があります。再試行してください。');}throw new Error('先の保存を確認してから、もう一度操作してください。');}return commit(patch,label,tenant,epoch);},true);},
  undo(){return enqueue(async(tenant,epoch)=>{
   if(!last)return;const previous=last,next=await read();if(next.tenant.id!==tenant||epoch!==generation)throw new Error('店舗が変更されました。');setState(next);
   if(Object.keys(previous.after).some(k=>!equal(next.settings[k]??defaults[k]??'',previous.after[k]))){last=null;onStatus('error','保存内容が別の画面で変更されています。最新の内容をご確認ください。');throw new Error('保存内容が別の画面で変更されています。');}
   return commit(previous.before,'直前の変更を元に戻しました',tenant,epoch,true);
  });},
  async recover(retry=false){const epoch=generation,tenant=getState().tenant.id;await tail;if(epoch!==generation||getState().tenant.id!==tenant)throw new Error('店舗が変更されました。');const next=await read();if(next.tenant.id!==tenant||epoch!==generation||getState().tenant.id!==tenant)throw new Error('店舗が変更されました。');setState(next);const task=failed,checkOnly=uncertain;failed=null;uncertain=false;
   if(retry&&task&&!checkOnly){if(Object.keys(task.patch).every(k=>equal(next.settings[k]??defaults[k]??'',task.before?.[k])))return this.save(task.patch,task.label);last=null;onStatus('error','保存内容が別の画面で変更されています。最新の内容をご確認ください。');return next;}last=null;onStatus('saved',checkOnly?'保存内容を再取得しました':'最新の保存内容を読み込みました');return next;
  },
  reset(){generation++;last=null;failed=null;uncertain=false;},
  get canUndo(){return !!last&&!pending&&!failed;},get undoKeys(){return last?Object.keys(last.before):[];},get pending(){return pending;},get failed(){return !!failed;},get uncertain(){return uncertain;},flush(){return tail;}
 };
}

