 function statusHTML(){if(status==='error'||status==='uncertain')return `<span class="store-save-error">${icon('warning')}${esc(message)}</span><button type="button" class="store-link" data-action="store-retry">${esc(status==='uncertain'?text('保存内容を確認','Check saved settings'):text('入力内容で再試行','Retry these changes'))}</button><button type="button" class="store-link" data-action="store-reload">${esc(text('最新の保存内容を読み込む','Load latest saved settings'))}</button>`;return `<span class="store-save-state">${status==='saved'?icon('check'):''}${esc(status==='saving'?text('保存中…','Saving…'):status==='saved'?(rows.some(r=>r.period&&!ruleValue(r))||(regionDraft?.state&&!regionDraft.region)?text('保存済み（選択途中の項目は未保存）','Saved (unfinished selections are not saved)'):text('保存済み','Saved')):status==='editing'?text('編集中：入力を終えると自動保存','Editing: saves when you finish'):text('選択がそろうと自動保存','Completed changes save automatically'))}</span>`;}
