// Acquisition is independent of rendering: a remote revision never rebases a draft.
const identity = context => JSON.stringify([context?.authEpoch, context?.user?.id, context?.user?.role, context?.user?.permissionVersion, context?.user?.permissions, context?.tenantId]);
const validRevision = value => Number.isSafeInteger(value) && value >= 0;
const validDay = value => /^\d{4}-\d{2}-\d{2}$/.test(value || '');
const syncError = (code, message) => Object.assign(new Error(message), {code});
const sameSnapshot = (a, b) => {
  if (!a || !b) return false;
  const {serverTime: _a, ...left} = a, {serverTime: _b, ...right} = b;
  return JSON.stringify(left) === JSON.stringify(right);
};

// Metadata can replace a full read only when every exposed policy/state key
// still agrees. Unknown user fields deliberately require the normal full read.
export function syncMetadataMatches(meta, snapshot) {
  return !!meta && !!snapshot && validRevision(meta.revision) && validDay(meta.today) &&
    !!meta.tenant?.id && !!meta.user?.id && !!meta.user?.role &&
    meta.revision === snapshot.revision && meta.today === snapshot.today &&
    meta.tenant.id === snapshot.tenant?.id && meta.tenant.slug === snapshot.tenant.slug &&
    JSON.stringify(meta.user) === JSON.stringify(snapshot.user) &&
    (meta.contentTranslationVersion || 0) === (snapshot.contentTranslationVersion || 0) &&
    (meta.timezone || '') === (snapshot.timezone || snapshot.settings?.timezone || '') &&
    JSON.stringify(meta.tenant.features || {}) === JSON.stringify(snapshot.tenant.features || {}) &&
    JSON.stringify(meta.tenant.integrationProfile || {}) === JSON.stringify(snapshot.tenant.integrationProfile || {});
}

export async function fetchMutationSnapshot({snapshot, fetchMetadata, fetchState}) {
  let meta;
  try { meta = await fetchMetadata(); }
  catch (error) {
    if (![404, 405, 501].includes(error.status)) throw error;
    return fetchState();
  }
  if (syncMetadataMatches(meta, snapshot)) return snapshot;
  const next = await fetchState();
  if (validRevision(meta?.revision) && next?.tenant?.id === meta.tenant?.id && next?.revision < meta.revision) {
    throw syncError('stale_sync_revision', 'Snapshot is older than sync metadata');
  }
  return next;
}

export function syncContextIdentity(context) {
  return identity(context);
}

// A request ID, arbitrary body.id or an unverified QR is never proof of an order ID.
export function resolveOrderReference(path, body, snapshot, context = {}) {
  const user = context.user || context.auth;
  const tenantId = context.tenantId || user?.tenant_id;
  if (!user?.id || !user?.role || !tenantId || snapshot?.tenant?.id !== tenantId ||
      snapshot?.user?.id !== user.id || snapshot?.user?.role !== user.role || !Array.isArray(snapshot?.orders)) return '';
  const known = id => typeof id === 'string' && id && snapshot.orders.filter(order => order?.id === id).length === 1 ? id : '';
  const route = String(path || '').split('?')[0];
  const payload = body && typeof body === 'object' ? body : {};
  const decode = value => { try { return decodeURIComponent(value); } catch { return ''; } };
  if (route === '/api/command' && String(payload.type || '').startsWith('order.')) return known(payload.payload?.id);
  const orderPath = route.match(/^\/api\/orders\/([^/]+)\/refund$/);
  if (orderPath) return known(decode(orderPath[1]));
  const requestPath = route.match(/^\/api\/refund-requests\/([^/]+)\/approve$/);
  if (requestPath) {
    const requests = (Array.isArray(snapshot.refundRequests) ? snapshot.refundRequests : []).filter(request => request?.id === decode(requestPath[1]));
    return requests.length === 1 ? known(requests[0].orderId) : '';
  }
  if (route === '/api/orders/scan' && typeof payload.token === 'string') {
    const token = payload.token.startsWith('EXOPS:') ? payload.token.slice(6) : payload.token;
    const orders = token ? snapshot.orders.filter(order => order?.qrToken === token) : [];
    return orders.length === 1 ? known(orders[0].id) : '';
  }
  return '';
}

