let sidebarAnimations=[];
function prepareSidebarMotion(){
 if(!document.documentElement.classList.contains('sidebar-layout'))return ()=>{};
 const workspace=$('#workspace');
 const workspaceLeft=workspace?.getBoundingClientRect().left;
 const handle=$('.sidebar-handle');
 const handleRect=handle?.classList?.contains('inset-handle')?handle.getBoundingClientRect():null;
 const nodes=[$('.sidebar'),$('.sidebar-closed-rail'),handle,$('.sidebar-handle .handle-chevron'),workspace].filter(Boolean);
 const from=nodes.map(node=>getComputedStyle(node).transform);
 sidebarAnimations.forEach(animation=>animation.cancel());sidebarAnimations=[];
 if(window.matchMedia('(prefers-reduced-motion: reduce)').matches||nodes.some(node=>!node.animate))return ()=>{};
 return ()=>{
  // Resolve the one workspace resize before starting the composited motion.
  const to=nodes.map(node=>getComputedStyle(node).transform);
  const rootStyle=getComputedStyle(document.documentElement);
  const zoom=Number.parseFloat(rootStyle.zoom)||1;
  if(handleRect){
   const target=handle.getBoundingClientRect(),i=nodes.indexOf(handle);
   from[i]=`translate3d(${(handleRect.left-target.left)/zoom}px,${(handleRect.top-target.top)/zoom}px,0) ${to[i]==='none'?'':to[i]} scale(${handleRect.width/target.width},${handleRect.height/target.height})`;
  }
  if(workspace){
   const offset=(workspaceLeft-workspace.getBoundingClientRect().left)/zoom;
   from[nodes.indexOf(workspace)]=`translate3d(${offset}px,0,0)`;
  }
  const duration=Number.parseFloat(rootStyle.getPropertyValue('--sidebar-duration'))||200;
  const easing=rootStyle.getPropertyValue('--sidebar-easing').trim()||'ease';
  const batch=nodes.map((node,i)=>node.animate([{transform:from[i]},{transform:to[i]}],{duration,easing,fill:'none'}));
  sidebarAnimations=batch;
  Promise.all(batch.map(animation=>animation.finished)).then(()=>{if(sidebarAnimations===batch)sidebarAnimations=[];},()=>{});
 };
}
