// ACTION_LAYER_MARKER
// Task 07: a protected draft owns its original revision until an explicit successful write.
function draftContext(){return {authEpoch,user:auth,tenantId:S?.tenant.id,state:S,
 revision:S?.revision,today:S?.today,lang,mode,online:navigator.onLine,busy,
 modal:!!$('#overlay-root .dialog')||!!scanContext,hasForm:!!document.querySelector('form[data-form]:not([data-form=login])')};}
const draftSafety=createDraftSafety({getContext:draftContext,getAppliedSnapshot:()=>S,
 isProtected:()=>busy||!!scanContext||!!$('#overlay-root .dialog')||!!document.querySelector('form[data-form]:not([data-form=login])')});
window.exopsDraftSafety=Object.assign(draftSafety,{captureView:()=>captureDraftScroll(),restoreView:restoreDraftScroll,activeScope:activeDraftScope,preflightMutation:preflightDraftMutation});
// Store settings already use their own serialized key-merge writer and immutable write revision.
function draftScopeFor(form){return form?.dataset?.form&&!['login','store'].includes(form.dataset.form)
 ?form.dataset.form+':'+(form.elements?.namedItem('id')?.value||'new'):null;}
function activeDraftScope(){if(scanContext&&$('#overlay-root .dialog'))return 'popup';if(page==='store'&&resumeStoreGuard)return 'store:resume';return draftScopeFor(document.querySelector('#overlay-root form[data-form]')||document.querySelector('#workspace form[data-form]'))
 ||($('#overlay-root .dialog')?'popup':undefined);}
function rememberDraftForms(){
 if(!S||!auth){draftSafety.reset();return;}
 draftSafety.adoptSnapshot(S,draftContext());
 const scopes=[...document.querySelectorAll('form[data-form]:not([data-form=login])')].map(draftScopeFor).filter(Boolean);
 if(productDraft)scopes.push('product:'+(productDraft.values?.id||productDraft.key?.split(':').pop()||'new'));
 if(designDraft)scopes.push('design:new');
 if($('#overlay-root .dialog'))scopes.push('popup');
 if(!scanContext)draftSafety.retainDrafts(scopes);
 for(const scope of scopes)draftSafety.beginDraft(scope);
 if($('#overlay-root .dialog'))draftSafety.beginDraft('popup');else draftSafety.endDraft('popup');
}
async function preflightDraftMutation({scope=activeDraftScope(),revision=S?.revision,compact=false}={}){
 if(!S||!auth)return;
 const context=draftContext(),snapshot=compact?await fetchMutationSnapshot({snapshot:S,
  fetchMetadata:()=>api('/api/sync'),fetchState:()=>api('/api/state')}):await api('/api/state');
 // Receiving a newer snapshot is never permission to rebase this form or popup.
 if(!draftSafety.observeSnapshot(snapshot,context)){
  throw new Error(t('店舗またはアカウントが変更されています。再ログインしてご確認ください。'));
 }
 try{draftSafety.assertCanMutate({scope,revision,context:draftContext()});}catch(error){error.message=t(error.message);throw error;}
 return snapshot;
}
async function draftSafeApi(path,options={}){
 const write=!['GET','HEAD'].includes((options.method||'GET').toUpperCase());
 if(!write)return api(path,options);
 let data;try{data=typeof options.body==='string'?JSON.parse(options.body):null;}catch{}
 const scope=activeDraftScope(),revision=data?.revision??draftSafety.revisionFor(scope,S?.revision);
 await preflightDraftMutation({scope,revision});
 const guarded=data&&typeof data==='object'&&!Array.isArray(data)?{...options,body:JSON.stringify({...data,revision})}:options;
 const result=await api(path,guarded);
 draftSafety.endDraft(scope);draftSafety.endDraft('popup');if(scope==='store:resume')resumeStoreGuard=false;
 return result;
}
