const qrReader=createQRReader({openModal,onManual:(reason='timeout')=>manualLookup(reason),setCleanup:fn=>{modalCleanup=fn;},esc,icon,getLang:()=>lang,
 isAllowed:()=>!!auth&&!!scanContext&&S?.tenant.id===scanContext.tenant&&location.hash===scanContext.route&&pageEnabled('orders'),
 async onToken(raw){const session=scanContext,tenant=S?.tenant.id;let token='';
  if(mode==='demo'&&/^EXOPS:[A-Za-z0-9_:.\-]+$/.test(raw))token=raw.slice(6);
  else if(mode==='demo'&&S.orders.some(o=>o.qrToken===raw))token=raw;
