import {dateFormatter,transactionDateParts} from './payment-time.mjs';
import {isOrderActionable} from './payment-guards.mjs';

export const TIMELINE_STATES=Object.freeze({incoming:'未処理',ready:'お渡し待ち',completed:'完了'});
const states=['all',...Object.keys(TIMELINE_STATES)],hh=h=>String(h).padStart(2,'0')+':00';
const civilCache=new Map();
function civilParts(ms,zone){
