}
function civilValue(ms,zone){const p=civilParts(ms,zone);return p?Date.parse(`${p.year}-${p.month}-${p.day}T${p.hour}:${p.minute}:${p.second}Z`)+((ms%1000)+1000)%1000:NaN;}
// Legacy pickup wall times belong to the store, never to the operator's device.
// Ambiguous/nonexistent DST wall times are not assigned an invented deadline.
export function pickupInstant(value,zone){
 if(typeof value!=='string'||transactionDateParts(value,{timeZone:zone,wall:true,language:'ja'}).time==='—')return NaN;
 if(/(?:Z|[+-]\d{2}:\d{2})$/i.test(value))return Date.parse(value);
 const key=zone+'|'+value;if(civilCache.has(key))return civilCache.get(key);
