 for(const delta of [-86400000,0,86400000]){const t=wall+delta;offsets.add(civilValue(t,zone)-t);}
 const matches=[...offsets].map(offset=>wall-offset).filter(ms=>civilValue(ms,zone)===wall),result=matches.length===1?matches[0]:NaN;
 if(civilCache.size>2000)civilCache.clear();civilCache.set(key,result);return result;
}
export function timelineFact(order,zone,now,{deadline='end'}={}){
 const start=pickupInstant(order.pickupAt,zone),end=pickupInstant(order.pickupEndAt,zone);
 const time=transactionDateParts(order.pickupAt,{timeZone:zone,wall:true,language:'ja'}).time;
 const hour=time==='—'?'unknown':Number(time.slice(0,2));
 const due=deadline==='end'&&Number.isFinite(end)&&end>=start?end:start;
 let urgency='normal',warning='';
 if(order.fulfillment!=='completed'&&isOrderActionable(order)&&Number.isFinite(now)&&Number.isFinite(start)){
  // The displayed end minute is inclusive: 09:00–09:30 becomes late at 09:31.
  if(now>=Math.floor(due/60000)*60000+60000){urgency='late';warning=`${Math.max(1,Math.floor((now-due)/60000))}分超過`;}
  else if(start>=now&&start-now<=600000){urgency='soon';warning=start===now?'受取時刻':`あと${Math.ceil((start-now)/60000)}分`;}
 }
 return {hour,start,due,urgency,warning};
}
const foldIcon=collapsed=>`<svg viewBox="0 0 18 18" aria-hidden="true"><path d="${collapsed?'M6 4l6 5-6 5M13 4v10':'M12 4L6 9l6 5M5 4v10'}"/></svg>`;
const set=(e,v)=>{if(e&&e.textContent!==String(v))e.textContent=String(v);};
const number=v=>Number.isFinite(v)?Math.max(0,v):0;
function cleanView(v={}){return {filter:states.includes(v.filter)?v.filter:'all',folded:Array.isArray(v.folded)?v.folded.filter(h=>Number.isInteger(h)&&h>=0&&h<24):[],left:number(v.left),tops:v.tops&&typeof v.tops==='object'?Object.fromEntries(Object.entries(v.tops).filter(([k,n])=>/^(\d|1\d|2[0-3]|unknown)$/.test(k)&&Number.isFinite(n)).map(([k,n])=>[k,number(n)])):{}};}

export function createOrderTimeline({esc,cardContent,canInteract=()=>true,onChange=()=>{}}){
