 const markup=()=>`<div id="order-order-view" class="kanban time-proposal" role="tabpanel" aria-labelledby="order-view-order"><div class="time-controls"><div class="time-toolbar"><span class="time-axis-title">受取時間帯</span><div class="time-filters" role="group" aria-label="注文の状態">${states.map(s=>`<button class="btn secondary time-filter" type="button" data-timeline-action="filter" data-filter="${s}" aria-pressed="${s==='all'}">${s==='all'?'すべて':TIMELINE_STATES[s]}</button>`).join('')}</div></div><div class="time-livebar"><span class="live-clock">現在時刻 <time>—</time></span>${countButton('soon','all','btn secondary global-alert','受取10分以内')}${countButton('late','all','btn secondary global-alert late','時間超過')}</div></div><div class="time-stage"><div class="time-scroll" tabindex="0" role="region" aria-label="受取時間帯、左右にスクロール"></div><section class="attention-panel" hidden aria-label="注意が必要なお客様"><header class="attention-head"><div><h2 class="attention-title"></h2><p class="attention-context"></p></div><span class="attention-total"><b>0</b>件</span><button type="button" class="btn secondary attention-return" data-timeline-action="back">一覧に戻る</button></header><div class="attention-results" tabindex="0" role="region" aria-label="該当するお客様の一覧"><p class="attention-empty" hidden>現在、該当するお客様はいません。</p></div></section></div><div class="time-footer"><span><b>横：受取時間 ↔</b>　｜　枠の中：お客様を上下に確認 ↕</span><span>時間帯の右上で折りたたみ・展開</span></div></div>`;
