 }
 function capture(){if(root?.isConnected){view.left=root.querySelector('.time-scroll').scrollLeft;for(const col of root.querySelectorAll('.time-column'))if(!col.classList.contains('is-collapsed'))view.tops[col.dataset.hour]=col.querySelector('.time-orders').scrollTop;}return cleanView(view);}
