 function mount(el){root=el;nodes.clear();detailNodes.clear();signature=new WeakMap();inspection=null;trigger=null;
  root.addEventListener('click',e=>{const b=e.target.closest('[data-timeline-action]');if(!b||!canInteract(b))return;e.preventDefault();action(b);onChange();});
  root.addEventListener('keydown',e=>{if(e.key==='Escape'&&inspection&&canInteract(root)){e.preventDefault();back();onChange();}});
