 function makeCard(o,f,map){let el=map.get(o.id);if(!el){el=document.createElement('button');el.type='button';el.className='order-card compact-order-card time-order';el.dataset.action='commerce-open';el.dataset.id=o.id;el.dataset.order=o.id;map.set(o.id,el);}
